class Solution:
    def pathSum(self, root: Optional[TreeNode], targetSum: int) -> int:
        prefix_count = defaultdict(int)
        prefix_count[0] = 1                      # the empty prefix: paths that start at the root

        def dfs(node: Optional[TreeNode], running: int) -> int:
            if not node:
                return 0
            running += node.val
            found = prefix_count[running - targetSum]   # paths ending here with the target sum
            prefix_count[running] += 1
            found += dfs(node.left, running) + dfs(node.right, running)
            prefix_count[running] -= 1                  # backtrack: leave this path
            return found

        return dfs(root, 0)
